// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        bytes32 otherHash = keccak256(abi.encodePacked("NotNuToken"));
        WrongBank wrong = new WrongBank(otherHash);

        vm.prank(actor);
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }

        vm.prank(address(wrong));
        try c.airDrop() { ok = true; } catch { ok = false; }

        assertTrue(c.tokenBalance(address(wrong)) == 0);
    }
}

contract WrongBank {
    bytes32 public hash;
    constructor(bytes32 h) { hash = h; }
    function supportsToken() external view returns (bytes32) {
        return hash;
    }
}
